// -----------------------------------------------------------------------------
// bob_clb - the cluster: 4 logic elements (LUT6, fracturable, 2 FFs), 16 inputs,
// 8 outputs, a full crossbar of 24:1 muxes per element input.
// M22: LUT contents and crossbar in CFGLUT5 (80 per CLB; M23 pairs the crossbar), loaded by
// hw/src/core/lut_loader.v as the tile's frames are written: lce[f] shifts tile frame f
// (0 xbar, 1 init, 2 init, 3 xbar), lcdi_* are the shared expander's
// bits (lut_expand.v). cfg: the element flags, element e at [12e +: 12] (BOB_ELE_*).
// -----------------------------------------------------------------------------
/* verilator lint_off DECLFILENAME */
module bob_clb (
    input  wire              clk, gce, gsr, gwe, ce, sr, cin,
    input  wire [15:0]       i,
    input  wire [47:0]       cfg,
    input  wire              lck,
    input  wire [3:0]        lce,
    input  wire [3:0]        lcdi_init,
    input  wire [71:0]      lcdi_x,
    output wire [7:0]       o,
    output wire              cout
);
    /* verilator lint_off UNUSEDSIGNAL */
    wire _unused = &{1'b0, lcdi_init, lcdi_x};     // not every slot is used by every CLB frame
    /* verilator lint_on UNUSEDSIGNAL */
    wire [4:0] cy;
    assign cy[0] = cin;
    assign cout  = cy[4];
    wire [5:0] x0;
    wire [5:0] x1;
    wire [5:0] x2;
    wire [5:0] x3;
    lxpair #(.S(24)) m0 (.in({o[7], o[6], o[5], o[4], o[3], o[2], o[1], o[0], i[15], i[14], i[13], i[12], i[11], i[10], i[9], i[8], i[7], i[6], i[5], i[4], i[3], i[2], i[1], i[0]}), .lck(lck), .lce(lce[0]), .lcdi(lcdi_x[0 +: 6]), .oa(x0[0]), .ob(x0[1]));
    lxpair #(.S(24)) m1 (.in({o[7], o[6], o[5], o[4], o[3], o[2], o[1], o[0], i[15], i[14], i[13], i[12], i[11], i[10], i[9], i[8], i[7], i[6], i[5], i[4], i[3], i[2], i[1], i[0]}), .lck(lck), .lce(lce[0]), .lcdi(lcdi_x[6 +: 6]), .oa(x0[2]), .ob(x0[3]));
    lxpair #(.S(24)) m2 (.in({o[7], o[6], o[5], o[4], o[3], o[2], o[1], o[0], i[15], i[14], i[13], i[12], i[11], i[10], i[9], i[8], i[7], i[6], i[5], i[4], i[3], i[2], i[1], i[0]}), .lck(lck), .lce(lce[0]), .lcdi(lcdi_x[12 +: 6]), .oa(x0[4]), .ob(x0[5]));
